// CSD_RATIONALE_BEGIN
// Root cause of 52% ceiling (attempt 43): premature span closure when
// `IsCompletePrefix` fires on minimal SQL like "SELECT city" that lacks FROM,
// WHERE, GROUP BY, and HAVING. Spider SQL always has a FROM clause; closing
// before FROM is emitted produces syntactically valid but semantically wrong output.
//
// Attempt 53 removed the IsCompletePrefix close entirely, which caused CloseSpanWithinBudget
// to fail to find good complete points → syntax dropped to 63%.
//
// This attempt keeps attempt 43's structure but adds a FROM-clause guard:
//   - IsCompletePrefix AND "FROM"/"from" found in constrained output → close immediately (same as attempt 43)
//   - IsCompletePrefix but NO FROM → call PenalizedConstrainedStep([eosToken], 5.0) to force
//     the model to continue generating FROM instead of stopping
//   - EOS at any point → close if IsCompletePrefix (preserves syntax)
//   - Phase 4 CloseSpanWithinBudget(80) fallback unchanged from attempt 43
//
// This targets the 184-sample mode_A cluster (fast, low-budget, ~60% syntax-invalid)
// which is caused by minimal complete SQL being closed before the FROM clause.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1: insideConstrainedOut flips true only on RenderedEndsWith(generated, "<<"),
//   at which point currentConstrainedOut := [] and IsValidPrefix([]) holds by precondition.
//   EOS break leaves insideConstrainedOut false; implication vacuous.
//
// Phase 2 (OpenConstrainedSpan): Only when !insideConstrainedOut && steps < maxSteps.
//   Sets currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 loop, "complete with FROM" branch: CloseConstrainedSpan requires IsCompletePrefix
//   (checked by the outer if), sets insideConstrainedOut := false; implication vacuous.
//
// Phase 3 loop, "complete without FROM" branch:
//   PenalizedConstrainedStep hard-masks to parser-valid + EOS; on non-EOS,
//   AppendConstrainedToken extends currentConstrainedOut by a valid token, preserving IsValidPrefix.
//   On EOS + close: CloseConstrainedSpan (guarded by IsCompletePrefix and steps<maxSteps check)
//   sets insideConstrainedOut := false; implication vacuous.
//   On EOS without close: break leaves insideConstrainedOut unchanged; invariant holds by induction.
//
// Phase 3 loop, normal branch (not complete): GroupBoostedConstrainedStep hard-masks to
//   parser-valid + EOS. AppendConstrainedToken preserves IsValidPrefix by parser-extension contract.
//   On EOS + complete: CloseConstrainedSpan sets insideConstrainedOut := false.
//   On EOS + not complete: break; invariant holds by induction.
//
// Phase 4: CloseSpanWithinBudget postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step; appends 0 (EOS) or 1 token. Ratio ≤ 1:1 per iteration.
//
// Phase 2: OpenConstrainedSpan costs +1 step; appends exactly 1 "<<". Strict 1:1.
//
// Phase 3, "complete with FROM": CloseConstrainedSpan costs +1 step; appends at most 1 ">>".
//   Net ≤ 1 token per +1 step; invariant preserved.
//
// Phase 3, "complete without FROM": PenalizedConstrainedStep costs +1 step; on non-EOS,
//   AppendConstrainedToken appends exactly 1 token (1:1). On EOS+close: +2 steps, ≤1 token.
//   On EOS without close: +1 step, 0 tokens; invariant strictly improves.
//
// Phase 3, normal: GroupBoostedConstrainedStep +1 step, AppendConstrainedToken +1 token (1:1).
//   On EOS+close: +2 steps, ≤1 token (">>" from close); invariant improves.
//   On EOS without close: +1 step, 0 tokens; invariant improves.
//
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| ≤ |generated| + closeBudget;
//   steps increases by closeBudget ≤ maxSteps - steps_before; net invariant preserved. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. Always include FROM clause with the correct table name. Include WHERE, GROUP BY, HAVING, ORDER BY, LIMIT when required by the question. No table aliases not defined in schema. No explanation outside the delimiters.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) to emit "SQL: "
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with FROM-clause guard
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  if parser.IsCompletePrefix(currentConstrainedOut) {
    // Check whether a FROM clause is present before closing
    var sqlStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var fromUpperCount := CSDHelpers.CountSubstring(sqlStr, "FROM");
    var fromLowerCount := CSDHelpers.CountSubstring(sqlStr, "from");
    if fromUpperCount + fromLowerCount > 0 {
      // FROM clause is present: close the span cleanly
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
      break;
    } else {
      // Complete but missing FROM: penalize EOS to push model toward FROM generation
      var next := helpers.PenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        [eosToken], 5.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // Model insists on EOS even with penalty; close if parse is complete
        if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  } else {
    // Not yet complete: hard constrained step with schema-token group boost
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

